parameters.jsCode:
// Junta el lead normalizado con lo que devolvio el modelo.
const salida = [];
for (const item of $input.all()) {
  const lead = $('Normalizar lead').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let ficha;
  try {
    ficha = JSON.parse(bruto);
  } catch (error) {
    ficha = { operacion: 'otro', zona: null, presupuesto: null, ref_inmueble: null, caracteristicas: [], urgencia: 'media', confianza: 0, motivo: 'respuesta no parseable: ' + bruto.slice(0, 150) };
  }
  salida.push({
    json: {
      ...lead,
      operacion: ficha.operacion ?? 'otro',
      zona: ficha.zona ?? '',
      presupuesto: ficha.presupuesto ?? '',
      ref_inmueble: ficha.ref_inmueble ?? '',
      urgencia: ficha.urgencia ?? 'media',
      confianza: Number(ficha.confianza ?? 0),
      motivo: ficha.motivo ?? '',
      estado: 'cualificado',
    },
  });
}
return salida;

